"""Generate analysis/modules.toml from the boundary scan + curated annotations.

usage: python3 -m wc1.modules_gen [--out analysis/modules.toml]
(runs modules_scan and modules_setup in-process; ~15 s)
"""
import argparse

from . import analysis, modules_names as mn, modules_scan as ms, modules_setup, path

HEADER = '''# Module (object-file) boundaries of war.exe's code object 0x10000..0x4212b.
# Generated by `python3 -m wc1.modules_gen` from tools/wc1/modules_scan.py
# (boundary rules) and tools/wc1/modules_names.py (curated names/notes).
# Method and caveats: docs/subsystems/modules.md.
#
# Schema ([[module]], sorted by start, contiguous, non-overlapping):
#   name             identifier; a guide name ("INIT.C") only with name_confidence >= low
#   start, end       code addresses, end exclusive (= next module's start; the last
#                    ends at the code object end); both fall on discovered function starts
#   kind             game | gfx | asm | asm-shared | runtime | ail | resource
#   confidence       confidence that `start` is a real module start (verified|high|medium|low|speculative)
#   name_confidence  confidence in `name` (speculative for generic mod_XXXXX names)
#   candidates       optional: other guide names the evidence cannot exclude
#   evidence         list of concrete facts (addresses, bytes, strings)
# A range may still hold several modules whose starts leave no trace (module ends
# exactly 16-byte aligned); those are listed as open questions in the doc.
'''


def q(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=path("analysis", "modules.toml"))
    a = ap.parse_args()
    p = analysis.run()
    sc = ms.scan(p)
    import json
    shared = set(modules_setup.shared()[0])
    rule_conf = {"zero16": "medium", "zero4": "low", "zero2": "low"}
    bounds = {0x10000: ("medium", ["first byte of the code object (BEGTEXT stub of the startup object)"])}
    fd = {f["start"]: f for f in sc["funcs"]}
    for f in sc["funcs"]:
        if f["rule"] in rule_conf and f["start"] > 0x10010:
            r = f["rule"]
            al = {"zero16": 16, "zero4": 4, "zero2": 2}[r]
            bounds[f["start"]] = (rule_conf[r], [
                "preceded by %d zero byte(s) (linker alignment padding, never compiler fill) and %d-byte aligned (%s)" % (f["gap"], al, r)])
    for addr, (c, ev) in mn.EXTRA_BOUNDARIES.items():
        if addr in bounds:
            bounds[addr] = (bounds[addr][0], bounds[addr][1] + ev)
        else:
            bounds[addr] = (c, ev)
    starts = sorted(bounds)
    ends = starts[1:] + [sc["code_end"]]
    out = [HEADER]
    for s, e in zip(starts, ends):
        fs = [f for f in sc["funcs"] if s <= f["start"] < e]
        an = mn.ANNOT.get(s, {})
        kind = an.get("kind") or ("game" if s < 0x30bf0 else "runtime")
        ev = list(bounds[s][1])
        ev.append("%d functions, %#x bytes, %d at non-4-aligned addresses, %d byte-identical to setup.exe code" % (
            len(fs), e - s, sum(1 for f in fs if f["start"] % 4), sum(1 for f in fs if f["start"] in shared)))
        cw = ms.const_window(sc, s, e)
        if cw:
            ev.append("string/CONST pool slice referenced only from this range: %#x..%#x" % cw)
        ev += an.get("notes", [])
        name = an.get("name", "mod_%05x" % s)
        out.append("[[module]]")
        out.append("name = %s" % q(name))
        out.append("start = %#x" % s)
        out.append("end = %#x" % e)
        out.append("kind = %s" % q(kind))
        out.append("confidence = %s" % q(bounds[s][0]))
        out.append("name_confidence = %s" % q(an.get("name_confidence", "speculative")))
        if an.get("candidates"):
            out.append("candidates = [%s]" % ", ".join(q(c) for c in an["candidates"]))
        out.append("evidence = [")
        for x in ev:
            out.append("  %s," % q(x))
        out.append("]\n")
    missing = [hex(k) for k in mn.ANNOT if k not in bounds]
    open(a.out, "w").write("\n".join(out))
    print("modules:", len(starts), "annotations not at a module start:", missing)


if __name__ == "__main__":
    main()
